    echo
    while true
      do
        echo "Do you accept the license? [yn]: "
        read line leftover
        case ${line} in
          y* | Y*)
            cpack_license_accepted=TRUE
            break;;
          n* | N* | q* | Q* | e* | E*)
            echo "License not accepted. Exiting ..."
            exit 1;;
        esac
      done
  fi

  if [ "x${cpack_include_subdir}x" = "xx" ]
  then
    echo "By default the SCIPOptSuite will be installed in:"
    echo "  \"${toplevel}/SCIPOptSuite-7.0.2-Linux\""
    echo "Do you want to include the subdirectory SCIPOptSuite-7.0.2-Linux?"
    echo "Saying no will install in: \"${toplevel}\" [Yn]: "
    read line leftover
    cpack_include_subdir=TRUE
    case ${line} in
      n* | N*)
        cpack_include_subdir=FALSE
    esac
  fi
fi

if [ "x${cpack_include_subdir}x" = "xTRUEx" ]
then
  toplevel="${toplevel}/SCIPOptSuite-7.0.2-Linux"
  mkdir -p "${toplevel}"
fi
echo
echo "Using target directory: ${toplevel}"
echo "Extracting, please wait..."
echo ""

# take the archive portion of this file and pipe it to tar
# the NUMERIC parameter in this command should be one more
# than the number of lines in this header file
# there are tails which don't understand the "-n" argument, e.g. on SunOS
# OTOH there are tails which complain when not using the "-n" argument (e.g. GNU)
# so at first try to tail some file to see if tail fails if used with "-n"
# if so, don't use "-n"
use_new_tail_syntax="-n"
tail $use_new_tail_syntax +1 "$0" > /dev/null 2> /dev/null || use_new_tail_syntax=""

extractor="pax -r"
command -v pax > /dev/null 2> /dev/null || extractor="tar xf -"

tail $use_new_tail_syntax +289 "$0" | gunzip | (cd "${toplevel}" && ${extractor}) || cpack_echo_exit "Problem unpacking the SCIPOptSuite-7.0.2-Linux"

#### custom postinstall section ####
relink_binary() {
   BINARY=$1

   OLDLIBS=$(otool -L ${BINARY} | tail -n +2 | grep local | awk '{print $1}' )

   for l in ${OLDLIBS}; do
       BASENAME=$(basename $l)
       NEWLIB=$(find /usr/local -name ${BASENAME} | head -n 1)
       if test -z "${NEWLIB}"; then
           NEWLIB_GEN=$(echo ${BASENAME} | sed -e 's/[0-9.]*dylib//' ).dylib
           NEWLIB=$(find /usr/local -name ${NEWLIB_GEN} | head -n 1)
       fi
       if test -n "${NEWLIB}"; then
           install_name_tool -change $l ${NEWLIB} ${BINARY}
       fi
   done
   echo "Successfully relinked ${BINARY}"
}

if [ "Darwin" = "$(uname -s)" ]; then
   echo "Relinking libraries"
   for f in ${toplevel}/lib/*.dylib ${toplevel}/bin/*; do
     relink_binary $f
   done
fi
#### end custom postinstall section ####

echo "Unpacking finished successfully"

exit 0
